import getpass
import json
import os
import pathlib
import platform
import socket
import subprocess
from datetime import datetime, timezone
from pathlib import Path

import psutil


def writeMetaData(args):
    Path(args.resultsDirectory).mkdir(parents=True, exist_ok=True)
    
    dateTime = datetime.now(timezone.utc).isoformat(timespec="seconds").replace("+00:00", "").split("T")
    with open(f"{args.resultsDirectory}/MetaData.json", "w") as fp:
        json.dump(
            {
                "comment": "This file was automatically generated by BLOOP",
                "date": dateTime[0],
                "time (UTC)": dateTime[1],
                "user": getpass.getuser(),
                "host machine": socket.gethostname(),
                **getGitInfo(),
                "Python Version": platform.python_version(),
                "pip packages":  getDependcies(),
                "command": " ".join(psutil.Process(os.getpid()).cmdline()),
            } | vars(args),
        fp,
        indent=2
        )

def getGitInfo():
    return {
        key: subprocess.run(
            command, 
            capture_output=True, 
            text=True,
            check=False).stdout.splitlines()
        for key, command in {
            "git tag": ["git", "describe", "--tags", "--always"],
            "git branch": ["git", "rev-parse", "--abbrev-ref", "HEAD"],
            "dirty files": ["git", "status", "--porcelain"],
        }.items()
    }


def getDependcies():
    return subprocess.run(
        ["pip", "freeze"],
        capture_output=True,
        text=True,
        check=True
    ).stdout.splitlines()

